const cs = canary.filter(r=>r.path==='/search');
const ss = stable.filter(r=>r.path==='/search');
print('canary /search n=', cs.length, 'stable /search n=', ss.length);
print('canary p50/p95/p99/max', pct(cs.map(r=>r.ms),50), pct(cs.map(r=>r.ms),95), pct(cs.map(r=>r.ms),99), Math.max(...cs.map(r=>r.ms)));
print('stable p50/p95/p99/max', pct(ss.map(r=>r.ms),50), pct(ss.map(r=>r.ms),95), pct(ss.map(r=>r.ms),99), Math.max(...ss.map(r=>r.ms)));
for (const th of [200,300,500,1000]) {
  print('ms>'+th, 'canary', cs.filter(r=>r.ms>th).length, 'stable', ss.filter(r=>r.ms>th).length);
}
const slow = cs.filter(r=>r.ms>200).sort((a,b)=>a.t-b.t);
print('canary slow /search times:', slow.map(r=>Math.round(r.t)+'s/'+r.ms+'ms').join(' '));
print('status codes canary slow:', JSON.stringify(slow.map(r=>r.status)));
// all-path slow check on canary
const allSlow = canary.filter(r=>r.ms>200);
print('canary all slow>200ms by path:', JSON.stringify(allSlow.reduce((a,r)=>{a[r.path]=(a[r.path]||0)+1;return a;},{})));
print('stable all slow>200ms count:', stable.filter(r=>r.ms>200).length);
print('5xx canary', canary.filter(r=>r.status>=500).length, '5xx stable', stable.filter(r=>r.status>=500).length);
print('non-200 canary', JSON.stringify(canary.filter(r=>r.status!==200).map(r=>r.status)));

const cm = canary.filter(r=>r.path==='/search').map(r=>r.ms).sort((a,b)=>a-b);
const sm = stable.filter(r=>r.path==='/search').map(r=>r.ms).sort((a,b)=>a-b);
print('canary /search n='+cm.length, 'p50='+pct(cm,50), 'p95='+pct(cm,95), 'p99='+pct(cm,99), 'max='+cm[cm.length-1]);
print('stable /search n='+sm.length, 'p50='+pct(sm,50), 'p95='+pct(sm,95), 'p99='+pct(sm,99), 'max='+sm[sm.length-1]);
const cslow = cm.filter(m=>m>=600).length, sslow = sm.filter(m=>m>=600).length;
print('search >=600ms: canary='+cslow+' ('+(100*cslow/cm.length).toFixed(2)+'%) stable='+sslow+' ('+(100*sslow/sm.length).toFixed(2)+'%)');
print('search max: canary='+cm[cm.length-1]+' stable='+sm[sm.length-1]);
for (let w=0; w<4; w++) {
  const lo=w*30, hi=lo+30;
  const c = canary.filter(r=>r.path==='/search' && r.t>=lo && r.t<hi);
  print('window '+lo+'-'+hi+'s canary/search n='+c.length+' slow>=600ms='+c.filter(r=>r.ms>=600).length);
}
print('stable all >200ms: '+stable.filter(r=>r.ms>200).map(r=>r.path+'@'+r.t+'s/'+r.ms+'ms').join(' | '));
print('canary non-search >200ms: '+canary.filter(r=>r.ms>200 && r.path!=='/search').map(r=>r.path+'@'+r.t+'s/'+r.ms+'ms').join(' | '));
print('versions canary='+[...new Set(canary.map(r=>r.version))].join(',')+' stable='+[...new Set(stable.map(r=>r.version))].join(','));
print('5xx canary='+canary.filter(r=>r.status>=500).length+' 5xx stable='+stable.filter(r=>r.status>=500).length+' non200 canary='+canary.filter(r=>r.status!==200).length+' non200 stable='+stable.filter(r=>r.status!==200).length);
const cb=canary.filter(r=>r.path==='/browse').map(r=>r.ms).sort((a,b)=>a-b), sb=stable.filter(r=>r.path==='/browse').map(r=>r.ms).sort((a,b)=>a-b);
const cc=canary.filter(r=>r.path==='/checkout').map(r=>r.ms).sort((a,b)=>a-b), sc=stable.filter(r=>r.path==='/checkout').map(r=>r.ms).sort((a,b)=>a-b);
print('browse p99 canary='+pct(cb,99)+' stable='+pct(sb,99)+' | checkout p99 canary='+pct(cc,99)+' stable='+pct(sc,99));
print('gaps between canary slow searches (s): '+canary.filter(r=>r.path==='/search'&&r.ms>=600).map(r=>r.t).sort((a,b)=>a-b).join(','));

