{
  "decision": "ROLLBACK",
  "why": "The aggregate dashboard looks clean, but the raw log shows a /search-only tail-latency regression that exists only on the canary. 18 of 729 canary /search requests (2.5%) take >=600ms, while 0 of 2273 stable /search requests do (claim 1), and the canary /search max is 656ms vs 193ms on stable (claim 2). It is not a one-off blip: the slow canary searches are spread over all four 30s windows, 7 / 2 / 5 / 4 (claim 3). It is specific to /search - on /checkout the canary max is 301ms vs 343ms on stable (claim 4) - and nothing is failing: 0 5xx and 0 non-200 responses on both versions (claim 5). Judgement: a reproducible, version-specific jump of a slice of search traffic from under 200ms to ~650ms is a genuine defect in 1.1, not noise; because the canary is 1 pod of 4 it only serves about a quarter of traffic today, so promoting would expose roughly four times as many users to it. No errors means this is not an emergency, but the release should go back, get the search slow path fixed, and re-canary.",
  "claims": [
    {
      "claim": "18 of 729 canary /search requests took >=600ms, while 0 of 2273 stable /search requests did.",
      "query": "const c=canary.filter(r=>r.path==='/search'); const s=stable.filter(r=>r.path==='/search'); const cs=c.filter(r=>r.ms>=600).length; const ss=s.filter(r=>r.ms>=600).length; print('canary /search >=600ms: '+cs+' of '+c.length+' | stable /search >=600ms: '+ss+' of '+s.length);",
      "expect": "canary /search >=600ms: 18 of 729 | stable /search >=600ms: 0 of 2273"
    },
    {
      "claim": "The slowest canary /search request is 656ms; the slowest stable /search request is 193ms.",
      "query": "const c=canary.filter(r=>r.path==='/search').map(r=>r.ms); const s=stable.filter(r=>r.path==='/search').map(r=>r.ms); print('search max canary='+Math.max.apply(null,c)+'ms stable max='+Math.max.apply(null,s)+'ms');",
      "expect": "search max canary=656ms stable max=193ms"
    },
    {
      "claim": "The slow canary /search requests occur in every 30s window of the test: 7, 2, 5 and 4.",
      "query": "const w=[0,30,60,90].map(a=>canary.filter(r=>r.path==='/search'&&r.t>=a&&r.t<a+30&&r.ms>=600).length); print('canary /search >=600ms per window: w0-30='+w[0]+' w30-60='+w[1]+' w60-90='+w[2]+' w90-120='+w[3]+' total='+(w[0]+w[1]+w[2]+w[3]));",
      "expect": "w0-30=7 w30-60=2 w60-90=5 w90-120=4"
    },
    {
      "claim": "On /checkout the canary is not worse than stable: canary max 301ms vs stable max 343ms.",
      "query": "const mx=(v,p)=>Math.max.apply(null,v.filter(r=>r.path===p).map(r=>r.ms)); print('checkout max canary='+mx(canary,'/checkout')+' stable='+mx(stable,'/checkout')+' | browse max canary='+mx(canary,'/browse')+' stable='+mx(stable,'/browse'));",
      "expect": "checkout max canary=301 stable=343"
    },
    {
      "claim": "Neither version returned any 5xx or any non-200 response during the test.",
      "query": "const f=v=>v.filter(r=>r.status>=500).length; const n=v=>v.filter(r=>r.status!==200).length; print('5xx canary='+f(canary)+' stable='+f(stable)+' non200 canary='+n(canary)+' stable='+n(stable));",
      "expect": "5xx canary=0 stable=0 non200 canary=0 stable=0"
    }
  ]
}

