const sslow = ss.filter(r=>r.ms>200);
const pctl=(a,p)=>{const s=[...a].sort((x,y)=>x-y);return s[Math.min(s.length-1,Math.floor(p/100*s.length))];};
print('search slow canary='+cslow.length+'/'+cs.length+' stable_over200='+sslow.length+'/'+ss.length);
print('search max canaryMax='+Math.max(...cs.map(r=>r.ms))+' stableMax='+Math.max(...ss.map(r=>r.ms)));
print('search p99 canary='+pctl(cs.map(r=>r.ms),99)+' stable='+pctl(ss.map(r=>r.ms),99));
print('errors 5xx canary='+canary.filter(r=>r.status>=500).length+' stable='+stable.filter(r=>r.status>=500).length+' non200 canary='+canary.filter(r=>r.status!==200).length+' slowStatuses='+(cslow.every(r=>r.status===200)?'all200':'mixed'));
const w=[0,30,60,90].map(s=>cs.filter(r=>r.t>=s&&r.t<s+30&&r.ms>=600).length);
print('windows '+w.join(','));
print('pctSlow='+(100*cslow.length/cs.length).toFixed(2)+'%');
print('other paths canary over200 '+JSON.stringify(canary.filter(r=>r.ms>200&&r.path!=='/search').map(r=>r.path+'@'+r.ms)));

